import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class KWayListMergerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static List<Integer> nums(Integer... values) {
        return new ArrayList<>(Arrays.asList(values));
    }

    @SafeVarargs
    static List<List<Integer>> outer(List<Integer>... lists) {
        return new ArrayList<>(Arrays.asList(lists));
    }

    public static void main(String[] args) {
        try {
            check("merge three sorted lists", "[1, 2, 3, 4, 7, 9]",
                    KWayListMerger.merge(outer(nums(1, 4, 7), nums(2, 3), nums(9))).toString());
            check("merge of no lists", "[]",
                    KWayListMerger.merge(new ArrayList<List<Integer>>()).toString());
            check("merge of a single list", "[2, 5, 8]",
                    KWayListMerger.merge(outer(nums(2, 5, 8))).toString());
            check("empty and null inner lists are skipped", "[3, 6]",
                    KWayListMerger.merge(outer(nums(), nums(3, 6), null)).toString());
            check("duplicates are all kept", "[1, 1, 1]",
                    KWayListMerger.merge(outer(nums(1, 1), nums(1))).toString());
            check("negative values merge correctly", "[-9, -4, -1, 0, 2]",
                    KWayListMerger.merge(outer(nums(-9, -1), nums(-4, 0, 2))).toString());
            check("one list entirely before another", "[1, 2, 3, 40, 50]",
                    KWayListMerger.merge(outer(nums(1, 2, 3), nums(40, 50))).toString());
            check("total size adds up", 7,
                    KWayListMerger.merge(outer(nums(1, 5), nums(2, 2, 6), nums(0, 9))).size());
        } catch (Throwable t) {
            System.out.println("FAIL  unexpected exception: " + t);
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

