import java.util.ArrayList;
import java.util.List;

public class KWayListMerger {

    public static List<Integer> merge(List<List<Integer>> sortedLists) {
        List<Integer> merged = new ArrayList<>();
        int[] cursors = new int[sortedLists.size()];
        while (true) {
            int bestList = -1;
            int bestValue = 0;
            for (int i = 0; i < sortedLists.size(); i++) {
                List<Integer> current = sortedLists.get(i);
                if (current == null || cursors[i] >= current.size()) {
                    continue;
                }
                int value = current.get(cursors[i]);
                if (bestList == -1 || value < bestValue) {
                    bestList = i;
                    bestValue = value;
                }
            }
            if (bestList == -1) {
                return merged;
            }
            merged.add(bestValue);
            cursors[bestList]++;
        }
    }
}
